import{_ as a,o as t,c as n,ag as i}from"./chunks/framework.D5hoimZQ.js";const q=JSON.parse('{"title":"Kondo 效应的精确量子多体处理","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/quantum-physics/kondo-exact-many-body-2026.md","filePath":"topics/quantum-physics/kondo-exact-many-body-2026.md"}'),e={name:"topics/quantum-physics/kondo-exact-many-body-2026.md"};function r(l,o,s,u,d,h){return t(),n("div",null,[...o[0]||(o[0]=[i('<h1 id="kondo-效应的精确量子多体处理" tabindex="-1">Kondo 效应的精确量子多体处理 <a class="header-anchor" href="#kondo-效应的精确量子多体处理" aria-label="Permalink to &quot;Kondo 效应的精确量子多体处理&quot;">​</a></h1><blockquote><p>来源：Science · Toward an exact quantum many-body treatment of Kondo correlation in magnetic impurities（Tianyu Zhu, Linqing Peng, Huanchen Zhai, Zhi-Hao Cui 等, 2026-07-30） DOI: 10.1126/science.adq7402 关联：张量网络、多体问题、量子点、量子计算 状态：结构化知识 · 来源已核实</p></blockquote><hr><h2 id="一、一句话" tabindex="-1">一、一句话 <a class="header-anchor" href="#一、一句话" aria-label="Permalink to &quot;一、一句话&quot;">​</a></h2><p>凝聚态物理首次系统性地从<strong>第一性原理（ab initio）<strong>逼近对磁性杂质中 Kondo 关联的</strong>精确零温电子结构</strong>处理——从最经典的多体难题里，&quot;把工具箱修到了化学精度&quot;。</p><hr><h2 id="二、kondo-效应是什么-背景" tabindex="-1">二、Kondo 效应是什么（背景） <a class="header-anchor" href="#二、kondo-效应是什么-背景" aria-label="Permalink to &quot;二、Kondo 效应是什么（背景）&quot;">​</a></h2><ul><li>磁性杂质的<strong>局域电子</strong>与金属主体的<strong>巡游电子</strong>之间相互作用产生的量子现象。</li><li>几十年来一直是检验量子多体方法的&quot;试金石&quot;（testing ground）。</li><li>有材料特异性的<strong>精确</strong>描述长期困难。</li></ul><hr><h2 id="三、本工作的核心突破" tabindex="-1">三、本工作的核心突破 <a class="header-anchor" href="#三、本工作的核心突破" aria-label="Permalink to &quot;三、本工作的核心突破&quot;">​</a></h2><ol><li><strong>系统化的 ab initio 方法</strong>：在系列 3d 过渡金属中，收敛到 Kondo 关联的精确零温电子体处理。</li><li><strong>精确指标</strong>：提取的 <strong>Kondo 温度</strong> 与细微的实验结果匹配。</li><li><strong>方法家族</strong>：张量网络等先进多体方法——与量子计算主题下&quot;编码方案&quot;同一方法论家族。</li></ol><h3 id="前情-此前为何难" tabindex="-1">前情：此前为何难 <a class="header-anchor" href="#前情-此前为何难" aria-label="Permalink to &quot;前情：此前为何难&quot;">​</a></h3><ul><li>Kondo 是&quot;无穷自由度的强关联&quot;问题，精确解在计算上长期不可行。</li><li>磁性杂质嵌入金属主体 → 电子云与杂质自旋纠缠 → 需要处理无限游走电子与局部自旋的库仑纠缠。</li></ul><hr><h2 id="四、与我的知识网络连接" tabindex="-1">四、与我的知识网络连接 <a class="header-anchor" href="#四、与我的知识网络连接" aria-label="Permalink to &quot;四、与我的知识网络连接&quot;">​</a></h2><ul><li>与 <code>quantum-physics/</code> 下既有「超导量子模拟捕获临界态」是<strong>同一方法论家族</strong>：都用先进多体工具逼近强关联体系。</li><li>与量子计算主题的纠错编码同样共鸣：都体现&quot;用精细计算工具逼近精确解&quot;的路线。</li><li><strong>对量子点、重费米子材料的理解提供了新工具</strong>——这是&quot;工具箱级别的突破&quot;，不是单一材料的胜利。</li></ul><hr><h2 id="关联阅读" tabindex="-1">关联阅读 <a class="header-anchor" href="#关联阅读" aria-label="Permalink to &quot;关联阅读&quot;">​</a></h2><ul><li><a href="/zhishiku-reading/topics/quantum-physics/macro-entanglement-2026.html">宏观量子纠缠 2026</a></li><li><a href="/zhishiku-reading/topics/physics/quantum-computing-progress.html">量子计算前沿</a></li></ul>',19)])])}const m=a(e,[["render",r]]);export{q as __pageData,m as default};
